import Foundation

private typealias E = EvidenceSeed

/// Alternate tellings, batch D: the same cases, played out another way.
extension StoryVariants {
    static let variantsD: [CaseTemplate] = [ferryDeckStabbingV1, marinaHullCocaineV1, deerStandShootingV1, poolPartyDrowningV1, tractorTheftRingV1, ghostGunKitV1, promNightFentanylV1, landlordRentThreatV1, caretakerSavingsMoveV1, custodyExchangeFlightV1, rooftopPharmacyBreakInV1, hospitalBillingIdentityV1, tavernTruckShotsV1, fishPlantGhostPayrollV1, countyFuelDepotSkimV1, stagedCrashClaimV1, diningWitnessThreatV1, highSchoolPostThreatV1, bridgeRescueAssaultV1]

    static let ferryDeckStabbingV1 = SmallCases.make(
        key: "story.ferryDeckStabbing",
        category: .violent,
        headlines: ["Passenger Cut With Box Knife in Ferry Snack Line", "Crew Radios the Dock"],
        law: "awdwikisi",
        threshold: 7,
        spec: "Assaulted {V} with a knife, inflicting serious injury, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V} was cut across the forearm in the snack line of a ferry on {DATE} when a line dispute turned physical. {D} was holding a box knife used for cargo. {DL} says {V} grabbed {D.him}.",
        state: [E(.video, 3, "Snack Bar Camera", "{D} slashes at {V} in the line."), E(.physical, 3, "Box Knife", "A box knife in {D}'s coat.", .search), E(.forensic, 2, "Medical Report", "A six-inch forearm cut.")],
        defense: [E(.statement, 1, "Grabbed", "{DL} says {V} grabbed {D.him} first.")],
        role: "Snack bar worker",
        exam: [.direct("What is your job on the ferry?", "\"I work the snack bar on the passenger deck. I take orders, ring up sales, and keep the line moving during the crossing, which that day was about an hour.\""), .direct("What was the situation at about 1:20 p.m. on {DATE}?", "\"The line was long and the crossing was rough, so people were bumping into each other. Two passengers near the front were arguing about who was next at the counter.\""), .direct("Who was involved?", "\"{D} and {V}. {V} stood in front, and {D} was close behind. The argument got louder, and I could see it turning physical with all the shoving in the crowd.\""), .direct("What did you see {D} do?", "\"{D} pulled a box knife out of a coat and slashed at {V}'s forearm. It was fast, and {V} jerked back holding the arm. The snack bar camera caught it.\""), .direct("What did {V} look like afterward?", "\"Blood ran down the forearm and onto the deck. The cut was about six inches long. I grabbed napkins and clean towels from behind the bar and pressed them on it.\""), .direct("What did the crew do?", "\"Crew members separated them within a few minutes, around 1:30, and kept the two apart until we docked at 2. The box knife was in {D}'s coat when the crew checked.\""), .cross("Did you see {V} grab {D}?", "\"I saw them pressed close together and a lot of arms, but from behind the counter I could not see whether {V} gripped {D}'s sleeve.\""), .cross("Did you hear {D} say anything about cutting the line?", "\"I heard some heated talk. I am not certain of the words, but there was something said about the line, and I could not tell whether it was a joke.\""), .cross("Why did {D} have a box knife?", "\"{D} told the crew it was for opening cargo boxes at work. I cannot say if that was true, but the blade was a standard utility one.\""), .cross("Did {V} step toward {D} first?", "\"They were both pressed together by the people in line. I could not tell you who stepped toward whom, because the whole line was leaning with the boat.\""), .cross("How far were you from the incident?", "\"About eight feet, behind the counter, with customers between me and them. I had a decent view of the swing but not of their hands before it.\"")],
        defenseRole: "Passenger",
        defenseExam: [.direct("Where were you on the ferry?", "\"I was a passenger in the snack line, about four people behind {D} and {V}. I was waiting to buy a coffee for the crossing.\""), .direct("What did you see?", "\"{D} and {V} argued about who was next. It got loud, and they were jammed close together because of the crowd and the rocking.\""), .direct("What did {V} do?", "\"{V} reached out and grabbed at {D}'s sleeve. I saw {V}'s hand on {D}'s arm before anything else happened.\""), .direct("What happened next?", "\"{D} pulled something from a coat and swung it. {V} yelled and held {V.his} arm, and then people started shouting and backing away.\""), .direct("How did {D} react afterward?", "\"{D} looked shocked and stood completely still. {D} did not run and did not say anything while the crew came.\""), .direct("Did you speak with the crew?", "\"Yes. I told a crew member what I saw about the sleeve, and the crew member wrote my name down on a pad.\""), .cross("Did you see the knife before the swing?", "\"No. I only saw it when {D} swung. It all happened very quickly.\""), .cross("How far were you from them?", "\"About ten feet, with people standing in between. I saw them mostly between shoulders.\""), .cross("Did you hear what they said to each other?", "\"Not clearly. The line was loud, and I could only pick up fragments of the argument.\""), .cross("Did you hear {D} threaten {V}?", "\"I did not hear a threat. I heard anger and raised voices, but nothing I could repeat as a threat.\""), .cross("Do you know either of them?", "\"No. I am just another passenger who happened to be standing there.\"")],
        theory: ("{D} cut a passenger.", "A grab."),
        allocution: "\"I never meant to cut anyone.\"",
        truths: ("{DL} had threatened to 'cut the line' earlier.", "{V} gripped {D.his} sleeve before the cut."),
        defendant: [.direct("Why did you have a box knife on the ferry?", "\"I deliver cargo and open boxes for a living. The knife was in my coat from work, same as every day, and I never take it out unless I'm cutting tape.\""), .direct("What was happening in the snack line?", "\"It was crowded and the boat was rocking, and {V} and I started arguing about who was next. It was a stupid argument over a place in line.\""), .direct("What did {V} do?", "\"{V} grabbed my sleeve and pulled me hard. I felt trapped between {V} and the people behind me, and I reacted. I pulled the knife and swung.\""), .direct("Did you mean to cut {V}?", "\"I meant to make {V} let go of me. I did not plan to hurt anyone, and I never thought the blade would reach an arm.\""), .direct("Did you say you would cut the line?", "\"I may have said something like that earlier, as a joke about cutting in. It was a bad joke, and I know how it sounds now.\""), .direct("What did you do afterward?", "\"I stood still and put my hands where the crew could see them. They took me aside, and I handed over the knife without any argument.\""), .cross("You pulled a box knife in a crowded snack line, didn't you?", "\"Yes. I know how that sounds, and I should have walked away. I did not walk away, and someone got hurt.\""), .cross("The cut was six inches, wasn't it?", "\"That is what I have been told. I did not see it clearly at the time, because I was looking at {V}'s face.\""), .cross("{V} did not have a weapon, did {V.he}?", "\"No. {V} had nothing in {V.his} hands except a grip on my sleeve.\""), .cross("You could have stepped back, couldn't you?", "\"There was a crowd behind me, and the deck was moving. I'm not saying I could not have. I'm saying I felt pinned and I panicked.\""), .cross("You carried the knife in your coat on a passenger deck, didn't you?", "\"Yes. I'm used to having it for work, and I did not think about it being on me in a snack line.\"")],
        openings: ("In a crowded ferry snack line, {D} pulled a box knife from a coat and slashed {V}'s forearm, leaving a six-inch cut. The snack bar camera shows the swing, and the knife was found in {D}'s coat. You will hear from the snack bar worker who saw it.", "{D} says {V} grabbed {D.his} sleeve in a crowded line on a rocking boat. A passenger behind them saw the grab. The State must prove {D} did not act out of fear."),
        closings: ("A line dispute, a box knife, and a six-inch cut across a forearm, on camera. {D} carried the knife in a coat and used it on an unarmed person. {V} cannot grip a cup now.", "A rocking boat, a crowded line, and a grab at {D}'s sleeve seen by a passenger. The knife was a work tool carried every day. The State must prove {D} did not act out of fear."),
        timeline: [(0, "1:20 p.m.: the line."), (0, "1:25 p.m.: the cut."), (0, "1:30 p.m.: crew separate them."), (0, "2 p.m.: the dock.")],
        identified: "A camera and a knife.",
        aggravating: ["The offense involved a weapon"],
        mood: .divided,
        impact: "I can't grip a cup now.",
        doctrines: ["selfDefense"])

    static let marinaHullCocaineV1 = SmallCases.make(
        key: "story.marinaHullCocaine",
        category: .drugs,
        headlines: ["Cocaine Found in Dive Tanks on Charter Boat", "Dog Alerts at Dockside"],
        law: "traffickingCocaine",
        threshold: 7,
        spec: "Trafficked in 28 grams or more of cocaine by possession, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "Deputies at a charter dock on {DATE} found 520 grams of cocaine inside dive tanks on a boat leased by {D}. {DL} says the tanks were rented out.",
        state: [E(.forensic, 3, "Lab Report", "520 grams of cocaine."), E(.physical, 3, "Dive Tanks", "Packs sealed inside tanks.", .search), E(.document, 2, "Lease", "The boat leased by {D}.")],
        defense: [E(.document, 1, "Rental Log", "A log of tank rentals.")],
        role: "Deputy",
        exam: [.direct("What did you find at the charter dock?", "\"Deputies found 520 grams of cocaine packed and sealed inside dive tanks on a boat leased by {D}.\""), .direct("How was the cocaine hidden?", "\"Inside the dive tanks, in sealed packs. We opened the tanks during a search of the boat at the dock.\""), .direct("What does the lease show?", "\"That the boat was leased by {D}. The lease puts the boat and its equipment in {D}'s name.\""), .direct("How did deputies come to inspect the boat?", "\"A drug dog alerted on the charter dock around nine in the morning as we walked the slips. The dog kept returning to one boat leased by {D}.\""), .direct("What did you find in the tanks?", "\"Several dive tanks stored in the cabin had a false base. Inside were vacuum-sealed packages, and the lab later weighed 520 grams of cocaine.\""), .direct("Who held the lease on the boat?", "\"{D} signed the lease for the season and had keys. The lease lists no other named operator.\""), .cross("{D} says the tanks were rented out to customers, doesn't {D.he}?", "\"Yes. The rental log lists three renters that week, and I will agree that others used the tanks.\""), .cross("Did you find fingerprints on the packs?", "\"I do not have a print result that ties {D} to the packs. I would have to check the report.\""), .cross("Did anyone see {D} load the tanks?", "\"No. No one has said they saw {D} load cocaine into a tank.\""), .cross("Other people rented tanks from that boat, didn't they?", "\"A rental log lists three renters that week. I cannot say any of them handled the packages.\""), .cross("No cocaine was found on {D}'s person, was it?", "\"No. The drugs were only in the tanks on the boat.\"")],
        defenseRole: "Dive instructor",
        defenseExam: [.direct("Did other people use the dive tanks that week?", "\"Yes. We rent tanks to different groups all the time, and customers handle them without much supervision.\""), .direct("How many groups used the tanks that particular week?", "\"Three groups that I know of. I helped load tanks for two of them, and I saw the third group's gear.\""), .direct("Did {D} refill the tanks between groups?", "\"Yes. {D} refilled them as part of the normal routine. That is how the tanks are kept ready.\""), .direct("How do you know {D}?", "\"I am a dive instructor and sometimes teach students on {D}'s charters. We share equipment and trade tips.\""), .direct("How do the tank rentals work?", "\"Divers sign a log, take a tank, and return it after their trip. Tanks leave the boat several times a week.\""), .direct("What did you see about the tanks that week?", "\"Three groups rented them, and the tanks went back and forth. Nobody checked the bases.\""), .cross("Did you inspect the inside of each tank before renting it out?", "\"No. We check the valves and the pressure, not the inside. We do not open tanks to look.\""), .cross("Could someone have hidden packs in a tank without {D} knowing?", "\"It is possible, with a rental going in and out. But the tanks stay under our eye most days.\""), .cross("Did you see anyone putting packs into tanks that week?", "\"No. I never saw that. I only know about the rentals and refills.\""), .cross("You do not know what was inside any tank, do you?", "\"No. I only checked pressure on the ones I used.\""), .cross("{D} filled the tanks, didn't {D.he}?", "\"Yes, {D} handled most of the fills. I do not know who else touched them.\"")],
        theory: ("{D} hid cocaine in tanks.", "Rented tanks."),
        allocution: "\"I can't explain it.\"",
        truths: ("{DL} had refilled the tanks.", "The rental log lists three renters that week."),
        defendant: [.direct("Did you know there was cocaine in the dive tanks?", "\"No. I had no idea. I lease the boat and rent tanks out, and I did not know what customers did with them.\""), .direct("How do you handle the tanks?", "\"I refill them between groups and hand them back out. I check the pressure and the valves, not the inside.\""), .direct("Who rented the tanks that week?", "\"Three groups. The rental log lists each of them. Any of them could have put something inside.\""), .direct("What is your business on that boat?", "\"I rent dive equipment and run small charters for tourists. I lease the boat for the season and keep tanks in the cabin.\""), .direct("Who filled and handled the tanks?", "\"I filled them myself at a shop on the mainland. I rent them to divers, and three people rented tanks that week.\""), .direct("What do you say about the packages?", "\"I never saw them and I did not know the bases were hollow. Someone must have swapped tanks during a rental.\""), .cross("The cocaine was inside tanks on a boat you lease, wasn't it?", "\"Yes. That is what they found. I cannot explain it, and I did not put it there.\""), .cross("You refilled the tanks yourself. Wouldn't you notice something inside?", "\"Not through a sealed valve. I do not look inside a tank. I fill them.\""), .cross("520 grams is worth a lot. Why would a renter leave it behind?", "\"I do not know. Maybe it was not meant to be left. I did not know about it.\""), .cross("You had refilled those tanks yourself, hadn't you?", "\"Yes, and I did not unscrew the bases. I checked the pressure and nothing more.\""), .cross("The boat is leased in your name, isn't it?", "\"Yes. Anything found on it points to me, and I understand why.\"")],
        openings: ("Deputies at a charter dock found 520 grams of cocaine in sealed packs inside dive tanks on a boat leased by {D}. {D} refilled the tanks and had them in {D}'s possession.", "The defense case is that three groups rented the tanks that week, that no one saw {D} load anything, and that {D} knew nothing about the packs."),
        closings: ("520 grams of cocaine sealed inside dive tanks on {D}'s leased boat, tanks that {D} refilled. A boat owner answers for what is hidden aboard.", "Three rental groups and tanks that no one opens. The State must prove {D} knew the cocaine was inside, and a rented tank is not proof of knowledge."),
        timeline: [(-7, "The tanks are refilled."), (0, "9 a.m.: the dog alerts."), (0, "9:30 a.m.: tanks opened."), (0, "10 a.m.: arrest.")],
        identified: "A lab report.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        doctrines: ["searchSeizure", "mistakeOfFact"])

    static let deerStandShootingV1 = SmallCases.make(
        key: "story.deerStandShooting",
        category: .violent,
        headlines: ["Bow Hunter Struck by Rifle Round at Dawn", "Hunting Lease Argument Weeks Earlier"],
        law: "awdwisi",
        threshold: 7,
        spec: "Assaulted {V} with a deadly weapon, a rifle, inflicting serious injury, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V}, a bow hunter, was hit in the hip on {DATE} by a rifle round fired from a ridge. {D} held the adjoining lease. {DL} says {D.he} fired at a coyote.",
        state: [E(.forensic, 3, "Ballistics", "The bullet matches {D}'s rifle."), E(.statement, 3, "Hunting Partner", "'The shot came from {D}'s ridge.'"), E(.forensic, 2, "Medical Report", "A hip wound.")],
        defense: [E(.statement, 1, "Coyote", "{DL} says {D.he} fired at a coyote.")],
        role: "Wildlife officer",
        exam: [.direct("What is your job?", "\"I'm a state wildlife officer. I was called to a hunting lease on {DATE} after a hunter was shot at dawn, and I worked the scene.\""), .direct("What happened to {V}?", "\"{V}, a bow hunter, was hit in the hip by a rifle round fired from a ridge. {V} called out for help at about 6:30 a.m. and was taken out by ambulance.\""), .direct("Where did the shot come from?", "\"A ridge on the adjoining lease. {V}'s hunting partner told me the shot came from that ridge, and I walked the line of fire to confirm it.\""), .direct("Whose lease is the ridge?", "\"{D}'s. {D} held the adjoining lease and was out hunting there that morning. We found {D} on the ridge when we went up.\""), .direct("What did ballistics show?", "\"The bullet recovered matches {D}'s rifle. The lab report says the markings are consistent, and no other rifle was tested.\""), .direct("What did you do with {D}?", "\"I interviewed {D} at about 9 a.m. {D} said {D.he} had fired at a coyote and had not known anyone was across the draw.\""), .cross("Was a coyote seen that morning?", "\"Coyote scat was found on the ridge. I did not see a coyote, and neither did anyone I interviewed, but scat shows coyotes use the area.\""), .cross("Was {V} wearing blaze orange?", "\"Bow hunters often wear camouflage during archery season, and I would need my notes to say what {V} had on. I do not recall seeing orange.\""), .cross("How far apart were {D} and {V}?", "\"Several hundred yards across a draw. It was a long shot for a rifle in poor light, and trees cut up the view between the two.\""), .cross("Was there a known dispute between them?", "\"I heard of a boundary argument two weeks earlier. I do not know how serious it was or who raised it.\""), .cross("Was it light enough to see well when the shot was fired?", "\"It was dawn, and the light was low. Visibility was poor on both sides of the draw, and there was some ground fog.\"")],
        defenseRole: "Fellow hunter",
        defenseExam: [.direct("How do you know {D}?", "\"We hunt neighboring leases and have for about ten years. I see {D} at the feed store, and we trade information about deer and coyotes.\""), .direct("Were you out that morning?", "\"Yes, one ridge over from {D}. I heard a single shot and a few minutes later someone calling for help down the draw.\""), .direct("What was the coyote situation that season?", "\"Bad. Several of us had lost calves or chickens. A lot of people had been going up at dawn to try and thin them out.\""), .direct("How did {D} act after the shot?", "\"{D} came running down the ridge and helped with the call for help. {D} was shaking and kept saying that {D.he} thought it was a coyote.\""), .direct("Does {D} hunt carefully?", "\"Usually. I have seen {D} pass up shots when the light was poor, so what happened that morning surprised me.\""), .direct("What was the light like that morning?", "\"Poor. It was barely dawn, with fog hanging in the draw and shadows all over the slope. I could not see far even on my own ridge.\""), .cross("Did you see the shot?", "\"No. I only heard it. I was too far away to see anything.\""), .cross("Did you see a coyote that morning?", "\"No. I did not see one, though they were in the area that season.\""), .cross("Did {D} have a clear view of {V}?", "\"I cannot say. I was not next to {D}, and I do not know what {D} could see from that ridge.\""), .cross("Do you know about the boundary argument?", "\"I heard about it secondhand. As I understood it, it was a disagreement over a fence line, nothing worse.\""), .cross("How far were you from {D}?", "\"About half a mile along the ridge. I could hear but could not see {D} until afterward.\"")],
        theory: ("{D} shot a bow hunter.", "A coyote."),
        allocution: "\"I never saw {V.him}.\"",
        truths: ("{DL} had argued with {V} over boundary lines.", "Coyote scat lay on the ridge."),
        defendant: [.direct("What were you hunting that morning?", "\"Coyotes. They had been killing a neighbor's calves and chickens, and I went up before dawn to get a shot at them.\""), .direct("Did you see a coyote?", "\"I saw movement on the opposite slope in the low light and fired. I believed it was a coyote, and I had no idea a person was there.\""), .direct("Did you know someone was in that area?", "\"No. I did not know {V} was hunting that slope. I thought the property line put that ground out of anyone's use that morning.\""), .direct("What did you do when you heard the call?", "\"I stopped, unloaded the rifle, and walked down toward the shouting. I helped call for help, and I stayed until the wildlife officer came.\""), .direct("Had you argued with {V} before?", "\"We had words about the boundary a couple of weeks earlier. It was a disagreement over a fence line, not a threat of any kind.\""), .direct("How are you coping with what happened?", "\"Sick to my stomach. I never meant to hurt anyone, and I think about it every day.\""), .cross("The bullet matches your rifle, doesn't it?", "\"Yes. It came from my rifle. I am not going to dispute that.\""), .cross("You fired in low light at a target you could not identify, didn't you?", "\"I thought I could see a shape moving. Looking back, I should have waited until I could see clearly, and I did not.\""), .cross("You knew the boundary was close, didn't you?", "\"I knew it was somewhere near. I thought I was well inside my side, and I did not check my map.\""), .cross("You had argued with {V} about the line, hadn't you?", "\"Yes, we had. But I would never shoot at a person over a fence line, and I'd say that to anyone.\""), .cross("You never found a coyote, did you?", "\"No. We only found scat on the ridge afterward. The animal I fired at was gone.\"")],
        openings: ("At dawn on a hunting lease, a bow hunter was hit in the hip by a rifle round from a neighboring ridge. Ballistics match {D}'s rifle, and {V}'s partner places the shot on {D}'s ridge. {D} and {V} had argued about the boundary two weeks earlier.", "{D} fired at movement on a dark slope in low light, believing it was a coyote. Coyote scat lay on the ridge, and a fellow hunter will tell you about the coyote problem that season. {D} came running to help. The State must prove {D} acted knowingly."),
        closings: ("A rifle shot from {D}'s ridge, a bullet matching {D}'s rifle, and a hunter hit in the hip. {D} fired at something {D} could not identify in low light. {V} lost the season.", "Fog, low light, and a coyote problem make a tragic mistake. {D} ran to help and apologized. The State must prove more than carelessness."),
        timeline: [(-14, "The boundary argument."), (0, "Dawn: the shot."), (0, "6:30 a.m.: {V} calls out."), (0, "9 a.m.: {DL} is questioned.")],
        identified: "Ballistics.",
        aggravating: ["The offense involved a firearm"],
        mood: .divided,
        impact: "I lost the season.",
        doctrines: ["mistakeOfFact"],
        genders: ["D": .male, "V": .male])

    static let poolPartyDrowningV1 = SmallCases.make(
        key: "story.poolPartyDrowning",
        category: .violent,
        headlines: ["Toddler Drowns in Backyard Hot Tub During Cookout", "Gate Latch Was Broken"],
        law: "invManslaughter",
        threshold: 6,
        spec: "Unintentionally killed {V} without malice through culpable negligence, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V}, a three-year-old, drowned in a backyard hot tub on {DATE} during a cookout hosted by {D}. The hot tub gate latch was broken for weeks. {DL} says a guest was watching.",
        state: [E(.statement, 3, "Guest", "'No adult was near the tub.'"), E(.forensic, 3, "Autopsy", "Drowning."), E(.document, 2, "Repair Text", "{D} texted a plan to fix the latch.")],
        defense: [E(.statement, 1, "Guest", "{DL} says a guest was watching.")],
        role: "Party guest",
        exam: [.direct("What did you see at the cookout?", "\"{V}, a three-year-old, went into the backyard hot tub. No adult was near the tub, and the gate latch was broken.\""), .direct("How long had the latch been broken?", "\"For weeks. {D} had texted a plan to fix it, but the latch still did not close that day.\""), .direct("What did the autopsy show?", "\"Drowning. {V} was found in the hot tub.\""), .direct("What do you remember about the cookout?", "\"It was a crowded afternoon with kids running around the yard and adults talking by the grill. The hot tub sat near the back fence.\""), .direct("How was the hot tub secured?", "\"There was a gate with a latch, but the latch was loose and would not hold. I had heard it was broken for weeks.\""), .direct("What happened to {V}?", "\"Around three, someone found {V} floating face down in the hot tub. Several of us pulled {V} out and started CPR until paramedics arrived.\""), .cross("{D} says a guest was watching the tub, doesn't {D.he}?", "\"{D} asked an aunt to watch the tub. I did not know that at the time.\""), .cross("Had {D} been drinking?", "\"I saw {D} with two beers. I do not know more than that.\""), .cross("How many adults were at the party?", "\"Many. People were eating and talking, and everyone assumed someone else was watching the kids.\""), .cross("You did not see anyone watching the tub, did you?", "\"No adult was near it when I looked. People were at the grill and in the kitchen.\""), .cross("{D} said a guest was asked to watch, didn't {D.he}?", "\"I heard that afterward. I did not hear anyone say it at the time.\"")],
        defenseRole: "Aunt",
        defenseExam: [.direct("Did {D} ask you to watch the hot tub?", "\"Yes. {D} asked me to keep an eye on the tub while {D} grilled, and I said I would.\""), .direct("Were you there watching the tub?", "\"I stepped away. I went inside for a few minutes to help with the food, and I should have asked someone else.\""), .direct("Did you tell {D} you had left the tub?", "\"No. I did not. I thought I would be back in a minute. I did not know a child had gone in.\""), .direct("How are you related to {D}?", "\"I am {D}'s aunt, and I was at the cookout. I came early to help.\""), .direct("What did {D} ask you to do?", "\"To keep an eye on the hot tub while {D} cooked. I said I would.\""), .direct("What happened?", "\"I stepped away to answer a question in the kitchen and was gone a few minutes. When I came back, there was shouting.\""), .cross("How long were you away from the tub?", "\"A few minutes. It felt short, but it was enough. I think about it constantly.\""), .cross("Did you check the gate latch before leaving?", "\"No. I knew it was not working, but I assumed the kids were with their parents.\""), .cross("Did {D} check on you or the tub?", "\"I did not see that. {D} was busy at the grill and I did not see {D} come over.\""), .cross("You left your post, didn't you?", "\"Yes, for a few minutes. It was long enough.\""), .cross("You did not say anything to anyone before you left, did you?", "\"No. I assumed someone else was nearby.\"")],
        theory: ("{D} left a child unwatched.", "A guest watching."),
        allocution: "\"I'll never forgive myself.\"",
        truths: ("{DL} had drunk two beers.", "{DL} asked an aunt to watch the tub."),
        defendant: [.direct("Why was the hot tub gate not secured?", "\"The latch was broken for weeks. I texted a plan to fix it, and I did not get to it.\""), .direct("Did you ask someone to watch the tub?", "\"Yes. I asked an aunt to keep an eye on the tub during the cookout. I believed it was covered.\""), .direct("Had you been drinking?", "\"Two beers. I was grilling and serving food, and I was not drunk.\""), .direct("What was the plan for supervising the kids?", "\"I asked an aunt to keep an eye on the hot tub while I handled food. I thought I had covered it.\""), .direct("What about the latch?", "\"It had been loose for weeks and I texted a plan to fix it. I did not get to it before the party.\""), .direct("What had you been doing that afternoon?", "\"Cooking and talking with guests. I had two beers, and I was not paying attention to the kids.\""), .cross("The latch was broken for weeks, wasn't it?", "\"Yes. I knew. I should have fixed it or kept the tub covered.\""), .cross("A three-year-old drowned in your hot tub. Do you accept responsibility?", "\"I do. It is the worst thing that ever happened to me.\""), .cross("You relied on one person to watch the tub at a crowded party, didn't you?", "\"I did. I should have watched it myself or made sure the gate was locked.\""), .cross("You knew the latch was broken, didn't you?", "\"Yes. I knew for weeks and I did not fix it.\""), .cross("A three-year-old can climb a gate quickly, can't a child?", "\"Yes, and that is what makes it so painful.\"")],
