        defense: [E(.statement, 1, "Customer", "{DL} says a customer left them.")],
        role: "Undercover deputy",
        exam: [.direct("What was your assignment in this case?", "\"I'm an undercover deputy. I worked with an informant who set up a purchase with {D}, a convicted felon, on {DATE}.\""), .direct("How was the meeting arranged?", "\"The informant called {D} three days earlier and asked about buying pistols. {D} agreed to meet at 1 p.m. in a lot behind a shop.\""), .direct("What did {D} do at the meeting?", "\"{D} lifted the lid of a toolbox in a truck bed and showed three pistols. The informant's video captures it clearly, including the lid opening.\""), .direct("What was unusual about the pistols?", "\"They were kit-built, with no serial numbers anywhere on the frames. They looked assembled from parts rather than made by a manufacturer.\""), .direct("What happened after the showing?", "\"I gave the signal, and deputies moved in. {D} was arrested at about 1:05, and the pistols were seized from the toolbox.\""), .direct("What did you find at {D}'s shop?", "\"A search at 3 p.m. turned up a drill press and several unfinished kits. That fits with the way unserialed pistols like these are finished.\""), .cross("Did {D} say the pistols belonged to {D.him}?", "\"{D} said a customer had left them. I did not believe it, but that was {D}'s account and it was never contradicted by a name.\""), .cross("Was the customer ever identified?", "\"No. {D} did not give a name, and we have not located anyone matching that description.\""), .cross("Who made the pistols?", "\"We do not know. The tool marks and fingerprints on the frames were never compared with the equipment in the shop.\""), .cross("Did {D} take any money at the meeting?", "\"The informant had cash ready, but {D} had not accepted any before the arrest. The sale was not completed.\""), .cross("Who first raised the idea of selling pistols?", "\"The informant did, by phone, three days before. I was not on that call and I did not hear how the subject came up.\"")],
        defenseRole: "Shop neighbor",
        defenseExam: [.direct("What is your relationship to {D}?", "\"I run a shop next door. We share a wall, borrow tools, and I see {D} almost every day of the work week.\""), .direct("What kind of work does {D} do?", "\"Metal repair, mostly. {D} fixes lawn equipment, builds gates, and welds trailer hitches. It's an honest trade and a busy one.\""), .direct("Do customers leave items at the shop?", "\"All the time. People drop things off for repair and forget them for weeks. Everyone on our row has stuff in the back that isn't theirs.\""), .direct("Did you see anything unusual at the shop?", "\"I saw a few boxes come in during the weeks before the arrest. I did not look inside, and {D} never showed me what they held.\""), .direct("Does {D} have a drill press?", "\"Yes. Every metalwork shop has one. {D}'s is a floor model in the back corner, and I have used it myself.\""), .direct("Did {D} ever talk to you about pistols?", "\"No. Not once. {D} knows about the conviction and has always said {D.he} wants to stay clear of trouble.\""), .cross("Did you ever see {D} with a pistol?", "\"No, never. I never saw a firearm in {D}'s hands or in {D}'s truck.\""), .cross("Did you see {D} building anything like that?", "\"Not that I noticed. I'm next door, but I'm not watching the whole day.\""), .cross("Did a customer leave pistols at the shop?", "\"I cannot say. I never saw that, and I do not know what was in the back room.\""), .cross("Do you know about {D}'s record?", "\"I have heard about it, yes. It came up once, years ago, and {D} did not hide it.\""), .cross("Would you leave a gun at a repair shop?", "\"No, I would not. But I'm not {D}'s customer, and I cannot speak to what others do.\"")],
        theory: ("{D} sold kit pistols.", "A customer's items."),
        allocution: "\"I knew better.\"",
        truths: ("{DL} owned a drill press and kits.", "The customer's name was never given."),
        defendant: [.direct("What do you do for a living?", "\"I do metalwork and repair out of a small shop. I take in gates, lawn equipment, trailer hitches, anything that needs welding or drilling.\""), .direct("Where did the pistols come from?", "\"A customer left them with me to finish drilling a frame. I did not build them. I was only holding them in the toolbox until the customer came back.\""), .direct("Why did you meet the informant?", "\"I was told someone wanted to look at some work I had. I thought it was a customer coming to see the finished job.\""), .direct("Why did you open the toolbox?", "\"To show what was in there. I did not plan to sell anything, and I never named a price to the informant.\""), .direct("Why do you have a drill press and kits?", "\"I do metalwork, and I use the drill press for all sorts of jobs. The kits are leftovers from work I took in for other people.\""), .direct("Do you know you are not allowed to have firearms?", "\"Yes, because of my prior conviction. I should not have had those pistols anywhere near me, even for a customer.\""), .cross("You are a convicted felon, aren't you?", "\"Yes. I know I'm not allowed to be around firearms, and I knew it that day.\""), .cross("You cannot name the customer, can you?", "\"No. I'm not going to guess at a name, and I have not been able to find the person since.\""), .cross("You opened the toolbox for the informant, didn't you?", "\"Yes, I did. I lifted the lid myself, and I do not deny it.\""), .cross("The pistols had no serial numbers, did they?", "\"That's right. They had none. I'm told that's how kit-built frames are.\""), .cross("You had kits and a drill press at the shop, didn't you?", "\"I did. I use them for other work, and they have nothing to do with pistols for my regular customers.\"")],
        openings: ("{D}, who has a prior felony, met an informant at 1 p.m., opened a truck toolbox, and showed three kit-built pistols with no serial numbers. The informant video captured it, and a search of {D}'s shop found a drill press and kits. {D} was arrested minutes later.", "{D} says the pistols were a customer's and {D} was only holding them. The customer was never named, and no one proved who built them. The State must prove {D} was selling them."),
        closings: ("A convicted felon, a toolbox, three pistols with no serials, and a drill press at the shop. The video shows {D} opening the box. This is possession and sale of firearms by a felon.", "The customer was never identified, and the tool marks were never compared. {D} did not take the money. The State has not shown that {D} built or sold these pistols."),
        timeline: [(-3, "The informant calls."), (0, "1 p.m.: the toolbox."), (0, "1:05 p.m.: arrest."), (0, "3 p.m.: the shop search.")],
