        role: "Tenant",
        exam: [.direct("What did {D} tell you on that date?", "\"That {D} would 'call child services' unless I paid $900. A voicemail captured the demand.\""), .direct("How did it make you feel?", "\"Terrified. I thought I would lose my kids. I did not know what to do.\""), .direct("What did the voicemail say?", "\"'Pay or I make the call.' {D} said that unless I paid $900, {D} would call child services. {D} sounded calm and firm.\""), .direct("What was the money for?", "\"A fee {D} claimed I owed. It is not in my lease, and I told {D} so.\""), .direct("How did you feel?", "\"Terrified. I have kids and I thought I might lose them. I saved the voicemail and went to the Sheriff's Office.\""), .direct("What did you do after you heard the voicemail?", "\"I called a friend and then sat on the floor shaking. I saved the message and went to my lawyer to ask if it was legal.\""), .cross("{D} says it was a reminder, doesn't {D.he}?", "\"Yes. A maintenance worker says {D} may have meant a call to maintenance.\""), .cross("Does {D} sound angry on the voicemail?", "\"No. {D} sounds calm. That much is true.\""), .cross("Did you owe $900?", "\"No. I did not owe that. I had paid my rent.\""), .cross("{D} sounded calm on the message, didn't {D.he}?", "\"Yes. The tone was flat, which made it scarier.\""), .cross("You were behind on rent, weren't you?", "\"A little. That was a separate issue.\"")],
